// CI_Plus_Host_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module CI_Plus_Host_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_enable,
  input logic  c_ts_route,
  input logic  c_poll,
  input logic [3:0] c_setup,
  input logic [7:0] c_strobe,
  input logic [3:0] c_hold,
  input logic [15:0] c_wait_max,
  input logic [15:0] c_rst_clks,
  input logic [15:0] c_poll_div,
  input logic [15:0] c_fr_max,
  input logic [31:0] c_cis_addr,
  input logic [15:0] c_cis_len,
  input logic [14:0] c_cor_addr,
  input logic [7:0] c_cor_val,
  input logic [31:0] c_tx_addr,
  input logic [15:0] c_tx_len,
  input logic [31:0] c_rx_addr,
  input logic [15:0] c_rx_max,
  input logic  c_power_on,
  input logic  c_power_off,
  input logic  c_cis_read,
  input logic  c_cor_write,
  input logic  c_if_reset,
  input logic  c_tx_start,
  input logic  c_rx_arm,
  input logic  c_powered,
  input logic  c_ready,
  input logic  c_io_mode,
  input logic  c_busy,
  input logic  c_rx_full,
  input logic  c_rx_ovf,
  input logic  c_tx_fail,
  input logic  c_err,
  input logic  c_present,
  input logic [7:0] c_last_st,
  input logic [15:0] c_rx_len,
  input logic [15:0] c_tx_cnt,
  input logic [15:0] c_rx_cnt,
  input logic [15:0] c_ts_cnt,
  input logic [15:0] c_to_cnt,
  input logic  c_det,
  input logic  c_rdy,
  input logic  c_cfg,
  input logic  c_tx_done,
  input logic  c_rx,
  input logic  c_ireq,
  input logic  c_bus_to,
  input logic  c_err_irq
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 22;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:21];          // model of every stored word
  logic [7:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_det) m_set[0] = 1'b1;
    if (c_rdy) m_set[1] = 1'b1;
    if (c_cfg) m_set[2] = 1'b1;
    if (c_tx_done) m_set[3] = 1'b1;
    if (c_rx) m_set[4] = 1'b1;
    if (c_ireq) m_set[5] = 1'b1;
    if (c_bus_to) m_set[6] = 1'b1;
    if (c_err_irq) m_set[7] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h7;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'h7FFFFF;
      if (m_wr && m_map && m_idx == 12) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 13) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 14) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 15) m_w[15] <= ((m_w[15] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 16) ? PWDATA & m_be & 32'h7F : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h7C0B0100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return m_w[14];
      15: return m_w[15];
      16: return 0;
      17: return (32'(c_powered) << 0) | (32'(c_ready) << 1) | (32'(c_io_mode) << 2) | (32'(c_busy) << 3) | (32'(c_rx_full) << 4) | (32'(c_rx_ovf) << 5) | (32'(c_tx_fail) << 6) | (32'(c_err) << 7) | (32'(c_present) << 8);
      18: return (32'(c_last_st) << 0);
      19: return (32'(c_rx_len) << 0);
      20: return (32'(c_tx_cnt) << 0) | (32'(c_rx_cnt) << 16);
      21: return (32'(c_ts_cnt) << 0) | (32'(c_to_cnt) << 16);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][7:0] & m_w[2][7:0]))
  `SVA_INV(a_core_enable, c_enable == m_w[5][0:0])
  `SVA_INV(a_core_ts_route, c_ts_route == m_w[5][1:1])
  `SVA_INV(a_core_poll, c_poll == m_w[5][2:2])
  `SVA_INV(a_core_setup, c_setup == m_w[6][3:0])
  `SVA_INV(a_core_strobe, c_strobe == m_w[6][11:4])
  `SVA_INV(a_core_hold, c_hold == m_w[6][15:12])
  `SVA_INV(a_core_wait_max, c_wait_max == m_w[7][15:0])
  `SVA_INV(a_core_rst_clks, c_rst_clks == m_w[7][31:16])
  `SVA_INV(a_core_poll_div, c_poll_div == m_w[8][15:0])
  `SVA_INV(a_core_fr_max, c_fr_max == m_w[8][31:16])
  `SVA_INV(a_core_cis_addr, c_cis_addr == m_w[9][31:0])
  `SVA_INV(a_core_cis_len, c_cis_len == m_w[10][15:0])
  `SVA_INV(a_core_cor_addr, c_cor_addr == m_w[11][14:0])
  `SVA_INV(a_core_cor_val, c_cor_val == m_w[11][22:15])
  `SVA_INV(a_core_tx_addr, c_tx_addr == m_w[12][31:0])
  `SVA_INV(a_core_tx_len, c_tx_len == m_w[13][15:0])
  `SVA_INV(a_core_rx_addr, c_rx_addr == m_w[14][31:0])
  `SVA_INV(a_core_rx_max, c_rx_max == m_w[15][15:0])
  `SVA_INV(a_core_power_on, c_power_on == m_pulse_CMD[0])
  `SVA_INV(a_core_power_off, c_power_off == m_pulse_CMD[1])
  `SVA_INV(a_core_cis_read, c_cis_read == m_pulse_CMD[2])
  `SVA_INV(a_core_cor_write, c_cor_write == m_pulse_CMD[3])
  `SVA_INV(a_core_if_reset, c_if_reset == m_pulse_CMD[4])
  `SVA_INV(a_core_tx_start, c_tx_start == m_pulse_CMD[5])
  `SVA_INV(a_core_rx_arm, c_rx_arm == m_pulse_CMD[6])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_enable == 1'h0 && c_ts_route == 1'h0 && c_poll == 1'h0 && c_setup == 4'h0 && c_strobe == 8'h0 && c_hold == 4'h0 && c_wait_max == 16'h0 && c_rst_clks == 16'h0 && c_poll_div == 16'h0 && c_fr_max == 16'h0 && c_cis_addr == 32'h0 && c_cis_len == 16'h0 && c_cor_addr == 15'h0 && c_cor_val == 8'h0 && c_tx_addr == 32'h0 && c_tx_len == 16'h0 && c_rx_addr == 32'h0 && c_rx_max == 16'h0 && c_power_on == 1'h0 && c_power_off == 1'h0 && c_cis_read == 1'h0 && c_cor_write == 1'h0 && c_if_reset == 1'h0 && c_tx_start == 1'h0 && c_rx_arm == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_TIMING, m_rd && m_map && m_idx == 6)
  `FC(wr_TIMING, m_wr && m_map && m_idx == 6)
  `FC(rd_WAITS, m_rd && m_map && m_idx == 7)
  `FC(wr_WAITS, m_wr && m_map && m_idx == 7)
  `FC(rd_POLL, m_rd && m_map && m_idx == 8)
  `FC(wr_POLL, m_wr && m_map && m_idx == 8)
  `FC(rd_CIS_ADDR, m_rd && m_map && m_idx == 9)
  `FC(wr_CIS_ADDR, m_wr && m_map && m_idx == 9)
  `FC(rd_CIS_LEN, m_rd && m_map && m_idx == 10)
  `FC(wr_CIS_LEN, m_wr && m_map && m_idx == 10)
  `FC(rd_COR, m_rd && m_map && m_idx == 11)
  `FC(wr_COR, m_wr && m_map && m_idx == 11)
  `FC(rd_TX_ADDR, m_rd && m_map && m_idx == 12)
  `FC(wr_TX_ADDR, m_wr && m_map && m_idx == 12)
  `FC(rd_TX_LEN, m_rd && m_map && m_idx == 13)
  `FC(wr_TX_LEN, m_wr && m_map && m_idx == 13)
  `FC(rd_RX_ADDR, m_rd && m_map && m_idx == 14)
  `FC(wr_RX_ADDR, m_wr && m_map && m_idx == 14)
  `FC(rd_RX_MAX, m_rd && m_map && m_idx == 15)
  `FC(wr_RX_MAX, m_wr && m_map && m_idx == 15)
  `FC(rd_CMD, m_rd && m_map && m_idx == 16)
  `FC(wr_CMD, m_wr && m_map && m_idx == 16)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 17)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 17)
  `FC(rd_LAST_ST, m_rd && m_map && m_idx == 18)
  `FC(wr_LAST_ST, m_wr && m_map && m_idx == 18)
  `FC(rd_RX_LEN, m_rd && m_map && m_idx == 19)
  `FC(wr_RX_LEN, m_wr && m_map && m_idx == 19)
  `FC(rd_COUNTS, m_rd && m_map && m_idx == 20)
  `FC(wr_COUNTS, m_wr && m_map && m_idx == 20)
  `FC(rd_TS_TO, m_rd && m_map && m_idx == 21)
  `FC(wr_TS_TO, m_wr && m_map && m_idx == 21)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_DET_set, m_set[0])
  `FC(irq_DET_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_DET_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_DET_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_READY_set, m_set[1])
  `FC(irq_READY_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_READY_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_READY_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_CFG_set, m_set[2])
  `FC(irq_CFG_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_CFG_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_CFG_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_TX_DONE_set, m_set[3])
  `FC(irq_TX_DONE_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_TX_DONE_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_TX_DONE_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_RX_set, m_set[4])
  `FC(irq_RX_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_RX_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_RX_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_IREQ_set, m_set[5])
  `FC(irq_IREQ_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_IREQ_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_IREQ_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_BUS_TO_set, m_set[6])
  `FC(irq_BUS_TO_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_BUS_TO_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_BUS_TO_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(irq_ERR_set, m_set[7])
  `FC(irq_ERR_cleared, m_w[1][7] && m_wr && m_map && m_idx == 1 && PWDATA[7] && PSTRB[0])
  `FC(irq_ERR_masked, m_w[1][7] && !m_w[2][7])
  `FC(irq_ERR_drives_pin, m_w[1][7] && m_w[2][7] && irq)
  `FC(cmd_power_on, m_pulse_CMD[0])
  `FC(cmd_power_off, m_pulse_CMD[1])
  `FC(cmd_cis_read, m_pulse_CMD[2])
  `FC(cmd_cor_write, m_pulse_CMD[3])
  `FC(cmd_if_reset, m_pulse_CMD[4])
  `FC(cmd_tx_start, m_pulse_CMD[5])
  `FC(cmd_rx_arm, m_pulse_CMD[6])
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind CI_Plus_Host_apb CI_Plus_Host_apb_sva u_apb_sva (.*);
